// Classe chaque tâche en retard / aujourd'hui / demain (timezone America/Toronto),
// ignore les tâches dont l'échéance est plus lointaine, puis regroupe par user_id.
// Les tâches déjà 'done' sont exclues en amont par la requête Supabase (status=neq.done).
const items = $input.all().map((i) => i.json);

const tz = "America/Toronto";

function dateStr(d) {
  // Convertit une date/heure absolue en chaîne YYYY-MM-DD selon le fuseau
  // Toronto, quel que soit le fuseau horaire du serveur qui exécute ce code.
  return new Date(d).toLocaleDateString("en-CA", { timeZone: tz });
}

function addDaysToDateStr(ymd, days) {
  // Arithmétique purement calendaire (Y-M-D) sur une chaîne déjà exprimée
  // dans le fuseau Toronto : Date.setDate() opère en heure locale du
  // serveur (pas forcément Toronto), donc on manipule uniquement des
  // composants Y-M-D via Date.UTC pour rester indépendant du fuseau serveur.
  const [y, m, d] = ymd.split("-").map(Number);
  const utcDate = new Date(Date.UTC(y, m - 1, d));
  utcDate.setUTCDate(utcDate.getUTCDate() + days);
  return utcDate.toISOString().slice(0, 10);
}

const todayStr = dateStr(new Date());
const tomorrowStr = addDaysToDateStr(todayStr, 1);

const byUser = {};

for (const task of items) {
  if (!task.due_date) continue;
  const due = dateStr(task.due_date);
  let bucket = null;
  if (due < todayStr) bucket = "overdue";
  else if (due === todayStr) bucket = "today";
  else if (due === tomorrowStr) bucket = "tomorrow";
  else continue; // hors périmètre du rappel (échéance plus lointaine)

  if (!byUser[task.user_id]) {
    byUser[task.user_id] = { user_id: task.user_id, overdue: [], today: [], tomorrow: [] };
  }
  byUser[task.user_id][bucket].push({
    title: task.title,
    priority: task.priority,
    due_date: task.due_date,
    project_title: (task.projects && task.projects.title) || "Non renseigné",
  });
}

// Seuls les utilisateurs ayant au moins une tâche pertinente (retard/aujourd'hui/demain)
// sont présents ici : un utilisateur sans échéance pertinente ne reçoit aucun e-mail.
return Object.values(byUser).map((u) => ({ json: u }));

// Construit le récapitulatif HTML pour un utilisateur, à partir des listes
// regroupées (retard/aujourd'hui/demain) et de l'e-mail récupéré via Auth
// admin. Amélioration UNIQUEMENT visuelle et de contenu : mêmes données en
// entrée (mêmes références de nœuds), même contrat de sortie
// ([{ json: { email, subject, html } }]), aucune nouvelle requête réseau,
// aucun credential modifié, aucune connexion modifiée. Aucune IA : le
// résumé en haut de l'e-mail est généré uniquement par des conditions
// JavaScript simples sur les compteurs overdue/today/tomorrow.
const authUser = $input.item.json; // { email, ... } via le nœud 'Récupérer l'e-mail Auth'
const grouped = $node["Regrouper par utilisateur"].json; // item courant, même index de branche

const appBaseUrl = $node["Configuration ProjectFlow"].json.APP_BASE_URL || "";

function esc(value) {
  return String(value == null ? "" : value).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

function plural(n, singular, pluralForm) {
  return n === 1 ? singular : pluralForm;
}

const PRIORITY_META = {
  high: { label: "Haute", color: "#ef4444", bg: "#fee2e2" },
  medium: { label: "Moyenne", color: "#d97706", bg: "#fef3c7" },
  low: { label: "Basse", color: "#16a34a", bg: "#dcfce7" },
};
function priorityMeta(priority) {
  return PRIORITY_META[priority] || { label: priority || "—", color: "#6b7280", bg: "#f3f4f6" };
}
function priorityBadge(priority) {
  const meta = priorityMeta(priority);
  return (
    '<span style="display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;' +
    'font-weight:600;color:' + meta.color + ';background:' + meta.bg + ';">' + esc(meta.label) + '</span>'
  );
}

function taskRow(t) {
  const due = t.due_date
    ? new Date(t.due_date).toLocaleDateString("fr-CA", { day: "numeric", month: "short", year: "numeric" })
    : "Sans échéance";
  return (
    '<li style="padding:10px 12px;border-bottom:1px solid #f1f2f4;list-style:none;display:flex;' +
    'justify-content:space-between;align-items:center;gap:8px;">' +
    '<span style="font-size:14px;color:#111827;">' + esc(t.title) + '<br/>' +
    '<span style="font-size:12px;color:#9ca3af;">📁 ' + esc(t.project_title) + '</span></span>' +
    '<span style="display:flex;align-items:center;gap:8px;white-space:nowrap;">' +
    priorityBadge(t.priority) +
    '<span style="font-size:12px;color:#6b7280;">' + esc(due) + '</span>' +
    '</span>' +
    '</li>'
  );
}

function sectionCard(icon, title, tasksList, accentColor, accentBg) {
  const count = tasksList ? tasksList.length : 0;
  const body =
    count > 0
      ? '<ul style="margin:0;padding:0;">' + tasksList.map(taskRow).join("") + '</ul>'
      : '<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:12px 14px;margin:12px 16px;">' +
        '<p style="margin:0;font-size:13px;color:#166534;">✅ Aucune tâche dans cette catégorie.</p>' +
        '</div>';
  return (
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-left:4px solid ' + accentColor + ';border-radius:12px;' +
    'margin-bottom:16px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="padding:12px 16px;background:' + accentBg + ';font-weight:600;color:#111827;font-size:14px;' +
    'display:flex;justify-content:space-between;align-items:center;">' +
    '<span>' + icon + ' ' + esc(title) + '</span>' +
    '<span style="font-size:12px;font-weight:700;color:' + accentColor + ';background:#ffffff;padding:2px 10px;border-radius:999px;">' + count + '</span>' +
    '</div>' +
    body +
    '</div>'
  );
}

const overdue = grouped.overdue || [];
const today = grouped.today || [];
const tomorrow = grouped.tomorrow || [];

// --- Résumé dynamique en haut de l'e-mail — conditions JavaScript pures,
// aucune IA. Le ton et le contenu s'adaptent au nombre de tâches en
// retard / aujourd'hui / demain, exactement comme pour le rapport
// hebdomadaire (mêmes seuils de tonalité : retard > 0 prioritaire,
// aucune tâche pertinente = message positif). ---
const totalPending = overdue.length + today.length + tomorrow.length;
let summaryText;
if (totalPending === 0) {
  summaryText = "Aucune échéance urgente pour le moment. Beau travail !";
} else if (overdue.length > 0) {
  summaryText =
    "Vous avez " + overdue.length + " " + plural(overdue.length, "tâche en retard", "tâches en retard") +
    ", " + today.length + " à échéance aujourd'hui et " + tomorrow.length +
    " demain. Pensez à traiter les tâches en retard en priorité.";
} else if (today.length > 0) {
  summaryText =
    "Vous avez " + today.length + " " + plural(today.length, "tâche à échéance aujourd'hui", "tâches à échéance aujourd'hui") +
    " et " + tomorrow.length + " demain. Bonne journée !";
} else {
  summaryText =
    "Aucune tâche urgente aujourd'hui, mais " + tomorrow.length + " " +
    plural(tomorrow.length, "tâche arrive à échéance demain", "tâches arrivent à échéance demain") + ".";
}

const linkHtml = appBaseUrl
  ? '<p style="text-align:center;margin:20px 0 0;">' +
    '<a href="' + esc(appBaseUrl) + '/tasks" ' +
    'style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:10px 22px;' +
    'border-radius:8px;font-size:13px;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,0.08);">Voir mes tâches dans ProjectFlow</a>' +
    '</p>'
  : "";

const html =
  '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Arial,sans-serif;color:#111827;max-width:560px;' +
  'margin:0 auto;background:#f9fafb;padding:20px;">' +

  // En-tête
  '<div style="text-align:center;margin-bottom:20px;">' +
  '<h1 style="font-size:20px;margin:0 0 6px;color:#111827;">👋 Bonjour !</h1>' +
  '<p style="font-size:13px;color:#6b7280;margin:0;">Voici votre résumé quotidien.</p>' +
  '</div>' +

  // Résumé dynamique (même style que le rapport hebdomadaire)
  '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:14px 16px;margin-bottom:16px;">' +
  '<p style="margin:0;font-size:13px;color:#1e3a8a;">' + esc(summaryText) + '</p>' +
  '</div>' +

  // Sections colorées
  sectionCard("🚨", "En retard", overdue, "#ef4444", "#fef2f2") +
  sectionCard("📅", "Aujourd'hui", today, "#d97706", "#fffbeb") +
  sectionCard("⏳", "Demain", tomorrow, "#2563eb", "#eff6ff") +

  linkHtml +

  // Pied de page
  '<div style="text-align:center;margin-top:24px;padding-top:16px;border-top:1px solid #e5e7eb;">' +
  '<p style="font-size:12px;color:#9ca3af;margin:0;font-weight:600;">ProjectFlow</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:6px 0 0;">Merci d\'utiliser ProjectFlow.</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Votre assistant intelligent de gestion de projets.</p>' +
  '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Rappel envoyé automatiquement chaque jour à 08:00.</p>' +
  '</div>' +

  '</div>';

return [{ json: { email: authUser.email, subject: "ProjectFlow — Rappel d'échéance", html } }];
